import{_ as t,o as e,c as a,ag as o}from"./chunks/framework.DaAXJYxM.js";const l=JSON.parse('{"title":"第35章 换本子","description":"","frontmatter":{},"headers":[],"relativePath":"第35章_换本子.md","filePath":"第35章_换本子.md"}'),_={name:"第35章_换本子.md"};function r(n,p,s,c,i,u){return e(),a("div",null,[...p[0]||(p[0]=[o('<h1 id="第35章-换本子" tabindex="-1">第35章 换本子 <a class="header-anchor" href="#第35章-换本子" aria-label="Permalink to &quot;第35章 换本子&quot;">​</a></h1><p>那年春节我是在家过的。</p><p>父母没回来。他们说年初三有一趟活，走不开。奶奶说习惯了。她说这话的时候在包馄饨，手很快，一个接一个。</p><p>年三十那天晚上我们两个人吃饭。她开了一瓶酒，是给我爷爷留下的那瓶，她自己不动。她说她一个人喝没意思。</p><p>电视开着，声音很大。她听不清，就一直问我说什么。我说没什么，就是跳舞。</p><p>零点的时候外面开始放炮。奶奶站起来走到窗边，看了一会儿，说今年放得多。</p><p>我在那个时候拿出手机看了一眼。</p><p>没有东西。</p><p>我把手机扣在桌上，回去陪她看。</p><p>初二初三两天，我跟奶奶去走亲戚。县城不大，走路就能从头到末。她走在前头，手里提着一盒饼干和一壶油。她走不快，一停下来就要人扶。我跟在后面，把手机揣在裤袋里，每走几步摸一下。</p><p>她不看我手机，她看我的脸。</p><p>第三天她跟一个亲戚说，这个从小就这样，出门就不自在。</p><p>那个亲戚笑了。我没辩。她说得对。</p><p>那两天我手机里一条新消息都没有。</p><p>我把这件事记在心里，不打算跟任何人讲。因为讲出来要解释，一解释就要说到她。</p><p>家里不知道她。我妈打电话来那天，奶奶顺口说了一句，说我在学校有个同学总写信来。</p><p>我妈问了很久。奶奶说不上来，就说反正是一个同学。</p><p>那件事我一直记得。我妈在电话那头停了一下，然后说了一句，哦。</p><p>那个&quot;哦&quot;里有很多东西。可我那时候没听出来。</p><p>初四晚上，沈聿给我发了一张图。是他家里的菜，一桌子，配了一句：你们南雾这个时候在吃什么。</p><p>我说，在吃剩的。</p><p>他说，一样。</p><p>我说，你那边过年冷吗。</p><p>他说，冷。但你们那边是湿的，我们这边是干的。</p><p>我说，对。</p><p>他说，你怎么了。</p><p>我说，没什么。</p><p>他说，你一个表情都没发。</p><p>我看了一眼屏幕，发现他说得对。我回他三句话，一个表情都没有。</p><p>我补了一个。</p><p>他回：你果然有事。</p><p>我说，真没有。</p><p>他没再问。沈聿这个人从来不多问第三遍。他后来跟我说过一次，他说他知道有些人不是不说，是说了也没用。</p><p>初五她来了一条消息。</p><p>她说：你在干嘛。</p><p>我说：看手机。</p><p>她说：大晚上的。</p><p>我说：睡不着。</p><p>她说：我也睡不着。</p><p>她说，我妈今天又说我成绩了。</p><p>我说，你说什么了。</p><p>她说，我没说话。</p><p>我说，不说话最难。</p><p>她隔了一会儿，回了一个字：嗯。</p><p>就这三个回合。她说她要睡了。我说好。</p><p>我躺在床上看天花板，看到外面有人在放最后一挂炮。</p><p>初六一早我睡回笼觉，醒过来的时候奶奶在楼下跟人说话。我坐在床上，把那个本子从架子上抽出来。</p><p>那本子是深蓝色封皮，巴掌大。写到这里已经快满了。我本来想的是把它腾一腾，把太早的几页往后挪一挪，给新的一年留出地方。</p><p>我把本子摊在床上，一页一页往前翻。</p><p>翻的过程比我想的长。我从最新的一页往回看，看到去年寒假，看到网课那一段，看到三月份。</p><p>中间有一段我完全不记得自己写过。字是我的，内容我想不起来当时为什么写。我坐在那儿想了十几分钟，才想起那天是在自修课上，我偷偷把本子垫在数学书下面抄的。</p><p>我看到她那句&quot;我最近很烦&quot;，看到那句&quot;你别记着&quot;，看到我自己写的&quot;她的表是假的&quot;。</p><p>我看到我在石凳上一天数的四趟车，看到那条回程票的日期。</p><p>我看得很慢。看着看着我发现一件事。</p><p>有三条，我不记得当时是什么时候写的了。</p><p>不是不记得事，是不记得话。</p><p>有一处我写的是一句很短的骂人的话，后面画了一个箭头。我想不起来她在骂谁。我想了很久，想到我连那天是不是下雨都记不起来。</p><p>还有一处更糟。有一页上我只写了日期，和两个字：她说。</p><p>后面是空的。</p><p>她说了什么，我当时没来得及写。我以为我现在肯定还记得。</p><p>我不记得了。</p><p>那天上午我坐在床边，把那页纸看了很久。</p><p>我试过各种办法。我按日期往前推，往后推，我把前后几页读了三遍。我甚至打开手机，把我们的记录从那一天翻起。</p><p>可那天我们的记录里什么都没有。她一整天没上线。</p><p>也就是说，她在那个下午对我说过一句话，那句话只有我一个人听到，而我现在把它丢了。</p><p>我那时候第一次怕了一件事。</p><p>我怕的不是我忘了。我怕的是有一天我会把整本都忘完，只剩一个本子。</p><p>本子不会替我记。本子上的字是我自己写的，我如果不认得了，它就只是一叠纸。</p><p>我拿笔在那两个字后面补了一句。</p><p>我补的是：忘了。</p><p>写完我想了想，又添了一行。</p><p>我添的是：她那天肯定说了很重要的话。</p><p>添完之后我看着这一行，觉得它像一个借口。</p><p>那天下午我把那本快满的本子留着，没有腾，去买了新的。</p><p>换本子那天我把里面所有的纸片一张一张挪过去，挪得很慢。</p><p>一张卡，一张包装纸，一张画，一张票。</p><p>我把它们按时间排好，从头到尾。</p><p>排完我数了一下，一共四张。</p><p>四张纸片，一年多的量。</p><p>我那时候觉得这个数不小。</p><p>四张纸，一张卡、一张包东纸、一张画、一张票。每一张都有日子，每一张我都知道它从哪里来。</p><p>后来我才懂，两年之后，这个数字也不会大多少。</p><p>那天夜里我做了最后一件事。</p><p>我打开手机，往上翻，翻到她去年说过的一句话。那句话我记得很清楚，我一个字一个字又看了一遍，看了很久。</p><p>然后我拿笔记在本子上。</p><p>那天晚上我一共誊了三句。</p><p>我以为我是在防忘。</p><p>后来我才知道，我是在把这些话存到一个只有我看得到的地方——因为说话的人自己，早晚会把它们收回去。</p>',88)])])}const m=t(_,[["render",r]]);export{l as __pageData,m as default};
